class Evaluator:
    def __init__(self, expr):
        self.expr = expr
        self.position = 0
        self.current_token = self.get_next_token()

    def get_next_token(self):
        while self.position < len(self.expr):
            char = self.expr[self.position]

            if char.isdigit() or char == '.':
                number = self._read_number()
                return ('NUMBER', number)

            if char in '+-*/()':
                self.position += 1
                return (char, char)

            self.position += 1

        return ('EOF', None)

    def _read_number(self):
        start = self.position
        while (self.position < len(self.expr) and 
               (self.expr[self.position].isdigit() or self.expr[self.position] == '.')):
            self.position += 1
        return float(self.expr[start:self.position])

    def parse(self):
        return self.expr_add_sub()

    def expr_add_sub(self):
        result = self.expr_mul_div()

        while self.current_token[0] in ('+', '-'):
            token = self.current_token
            self.current_token = self.get_next_token()
            if token[0] == '+':
                result += self.expr_mul_div()
            elif token[0] == '-':
                result -= self.expr_mul_div()

        return result

    def expr_mul_div(self):
        result = self.expr_parentheses()

        while self.current_token[0] in ('*', '/'):
            token = self.current_token
            self.current_token = self.get_next_token()
            if token[0] == '*':
                result *= self.expr_parentheses()
            elif token[0] == '/':
                divisor = self.expr_parentheses()
                if divisor == 0:
                    raise ValueError("Division by zero")
                result /= divisor

        return result

    def expr_parentheses(self):
        if self.current_token[0] == '(':
            self.current_token = self.get_next_token()
            result = self.expr_add_sub()
            if self.current_token[0] != ')':
                raise SyntaxError("Mismatched parentheses")
            self.current_token = self.get_next_token()
            return result
        else:
            number = self.current_token
            if number[0] == 'NUMBER':
                self.current_token = self.get_next_token()
                return number[1]
            raise SyntaxError("Unexpected token")

